#!/usr/bin/env python3
# -*- coding: utf-8 -*-

slides_part3 = [{'id': 17, 'title': 'Atomic History', 'subtitle': 'Quiz Challenge 1 (10 Questions): Philosophical Roots, Thomson, Rutherford & Bohr', 'speech': '', 'questions': [{'question': 'Q1. In the Vaisesika Sutras, Acharya Kanada proposed that matter (dravya) is made of indivisible particles called:', 'options': ['Electrons', 'Parmanus', 'Quarks', 'Isotopes'], 'answer': 1, 'solution_steps': ['Step 1: Recall Section 8.1 on ancient Indian atomic philosophy.', 'Step 2: Acharya Kanada proposed that matter (dravya) divides down to indivisible particles called parmanus.', 'Step 3: Parmanus combine into dyads and triads to form macroscopic matter.'], 'hint': 'Recall Section 8.1 on ancient Indian atomic philosophy.', 'explanation': 'Parmanus combine into dyads and triads to form macroscopic matter.'}, {'question': "Q2. Who coined the Greek term 'atomos' (meaning indivisible) in the 5th century BCE?", 'options': ['J. J. Thomson and Niels Bohr', 'Leucippus and Democritus', 'James Chadwick and Ernest Rutherford', 'John Dalton and Berzelius'], 'answer': 1, 'solution_steps': ["Step 1: 'Atomos' is a Greek word meaning uncuttable or indivisible.", 'Step 2: Ancient Greek philosophers Leucippus and Democritus coined this term.', 'Step 3: John Dalton later turned this concept into a scientific theory in 1808.'], 'hint': "'Atomos' is a Greek word meaning uncuttable or indivisible.", 'explanation': 'John Dalton later turned this concept into a scientific theory in 1808.'}, {'question': 'Q3. What did J. J. Thomson observe in 1897 that proved electrons exist in all atoms?', 'options': ['Alpha particles bounced off gold foil', 'Cathode rays had the exact same charge-to-mass ratio regardless of gas or electrode material', 'Helium weighed four times hydrogen', 'Light was emitted in discrete lines'], 'answer': 1, 'solution_steps': ['Step 1: Thomson tested different gases and different metal electrodes in cathode ray tubes.', 'Step 2: The negative particles produced were identical every time.', 'Step 3: This universality proved electrons are fundamental building blocks of all atoms.'], 'hint': 'Thomson tested different gases and different metal electrodes in cathode ray tubes.', 'explanation': 'This universality proved electrons are fundamental building blocks of all atoms.'}, {'question': 'Q4. What is the electric charge of a single electron?', 'options': ['+1.602 × 10⁻¹⁹ C', '-1.602 × 10⁻¹⁹ C', '0 C', '-9.1 × 10⁻³¹ C'], 'answer': 1, 'solution_steps': ['Step 1: An electron carries one fundamental unit of negative electric charge.', 'Step 2: Its magnitude is 1.602 × 10⁻¹⁹ C with a negative sign.', 'Step 3: Its relative charge is assigned as -1.'], 'hint': 'An electron carries one fundamental unit of negative electric charge.', 'explanation': 'Its relative charge is assigned as -1.'}, {'question': "Q5. In Thomson's Plum Pudding / Watermelon model, how is electrical neutrality maintained?", 'options': ['Neutrons cancel protons', 'Total positive charge of the uniform sphere equals total negative charge of embedded electrons', 'Electrons orbit outside the atom', 'The atom has no electric charges'], 'answer': 1, 'solution_steps': ['Step 1: Thomson pictured a uniform positive sphere (watermelon pulp) with negative electrons (seeds) inside.', 'Step 2: The total positive charge equals the total negative charge in magnitude.', 'Step 3: Equal and opposite charges cancel out, making the atom neutral.'], 'hint': 'Thomson pictured a uniform positive sphere (watermelon pulp) with negative electrons (seeds) inside.', 'explanation': 'Equal and opposite charges cancel out, making the atom neutral.'}, {'question': "Q6. In Geiger and Marsden's 1911 gold foil experiment, what particles were fired at the gold foil?", 'options': ['Electrons', 'Neutrons', 'Positively charged alpha (α) particles', 'X-rays'], 'answer': 2, 'solution_steps': ["Step 1: Rutherford's team aimed a beam of alpha (α) particles at ultra-thin gold foil.", 'Step 2: Alpha particles are doubly charged helium nuclei (+2).', 'Step 3: A circular zinc sulphide screen detected their scattering angles.'], 'hint': "Rutherford's team aimed a beam of alpha (α) particles at ultra-thin gold foil.", 'explanation': 'A circular zinc sulphide screen detected their scattering angles.'}, {'question': 'Q7. Roughly what fraction of alpha particles bounced straight back (~180°) in the gold foil experiment?', 'options': ['1 in 2', '1 in 10', '1 in 20,000', 'All of them'], 'answer': 2, 'solution_steps': ['Step 1: Most alpha particles passed straight through (proving empty space).', 'Step 2: A small fraction deflected through large angles.', 'Step 3: Only about 1 in 20,000 bounced back sharply off the tiny dense nucleus.'], 'hint': 'Most alpha particles passed straight through (proving empty space).', 'explanation': 'Only about 1 in 20,000 bounced back sharply off the tiny dense nucleus.'}, {'question': 'Q8. Approximately how many stacked atoms (diameter ~10⁻¹⁰ m) equal the thickness of a 0.1 mm sheet of paper?', 'options': ['100', '10,000', '1,000,000 (10⁶)', '10¹⁵'], 'answer': 2, 'solution_steps': ['Step 1: Convert paper thickness: 0.1 mm = 0.1 × 10⁻³ m = 10⁻⁴ m.', "Step 2: Divide by one atom's diameter (~10⁻¹⁰ m): 10⁻⁴ / 10⁻¹⁰ = 10⁶.", 'Step 3: About one million stacked atoms equal 0.1 mm.'], 'hint': 'Convert paper thickness: 0.1 mm = 0.1 × 10⁻³ m = 10⁻⁴ m.', 'explanation': 'About one million stacked atoms equal 0.1 mm.'}, {'question': "Q9. Why could Rutherford's planetary model NOT explain atomic stability?", 'options': ['Protons repel electrons out of the atom', 'Accelerating orbiting electrons should radiate energy continuously and spiral into the nucleus', 'Gold foil is radioactive', 'Nucleus has no mass'], 'answer': 1, 'solution_steps': ['Step 1: Circular motion is accelerated motion.', 'Step 2: According to classical electromagnetism, accelerating charges radiate energy.', 'Step 3: Losing energy would make electrons spiral inward and collapse into the nucleus.'], 'hint': 'Circular motion is accelerated motion.', 'explanation': 'Losing energy would make electrons spiral inward and collapse into the nucleus.'}, {'question': 'Q10. According to Niels Bohr (1913), when does an electron absorb or emit energy?', 'options': ['Continuously while moving in any orbit', 'Only when it jumps between discrete stationary energy levels (K, L, M, N...)', 'Only when the nucleus splits', 'Never under any condition'], 'answer': 1, 'solution_steps': ['Step 1: Inside a stationary orbit, an electron does not radiate energy.', 'Step 2: Jumping to a higher outer orbit requires absorbing a quantum of energy.', 'Step 3: Dropping to a lower inner orbit emits the energy difference.'], 'hint': 'Inside a stationary orbit, an electron does not radiate energy.', 'explanation': 'Dropping to a lower inner orbit emits the energy difference.'}]}, {'id': 18, 'title': 'Nucleus & Symbols', 'subtitle': 'Quiz Challenge 2 (10 Questions): Neutrons, BARC, IUPAC Symbols, Z & A', 'speech': '', 'questions': [{'question': 'Q1. Who discovered the neutron (n⁰) in 1932, and what is its electric charge?', 'options': ['J. J. Thomson; -1', 'James Chadwick; 0 (neutral)', 'Ernest Rutherford; +1', 'Niels Bohr; +2'], 'answer': 1, 'solution_steps': ['Step 1: Helium (2 protons) weighed 4 times hydrogen (1 proton), implying uncharged nuclear mass.', 'Step 2: In 1932, James Chadwick discovered the neutron.', 'Step 3: A neutron has zero electric charge and mass roughly equal to a proton.'], 'hint': 'Helium (2 protons) weighed 4 times hydrogen (1 proton), implying uncharged nuclear mass.', 'explanation': 'A neutron has zero electric charge and mass roughly equal to a proton.'}, {'question': 'Q2. What essential role do neutrons play inside heavy atomic nuclei?', 'options': ['They orbit in the K shell', 'They mitigate proton-proton electrostatic repulsion and supply strong nuclear binding force', 'They give the atom a negative charge', 'They determine chemical valency'], 'answer': 1, 'solution_steps': ['Step 1: Protons inside a tiny nucleus repel each other electrostatically.', 'Step 2: Neutrons add strong nuclear attraction without adding electrostatic repulsion.', 'Step 3: This stabilizes heavy nuclei.'], 'hint': 'Protons inside a tiny nucleus repel each other electrostatically.', 'explanation': 'This stabilizes heavy nuclei.'}, {'question': 'Q3. Where is the Bhabha Atomic Research Centre (BARC) and its Dhruva research reactor located?', 'options': ['Bengaluru', 'Mumbai', 'New Delhi', 'Kolkata'], 'answer': 1, 'solution_steps': ["Step 1: Recall India's Scientific Contributions in Section 8.3.", 'Step 2: BARC is located in Mumbai and was founded under Homi Jehangir Bhabha.', 'Step 3: The Dhruva reactor produces neutrons for research, medicine, and agriculture.'], 'hint': "Recall India's Scientific Contributions in Section 8.3.", 'explanation': 'The Dhruva reactor produces neutrons for research, medicine, and agriculture.'}, {'question': "Q4. Who proposed alphabetic chemical symbols in 1813 to replace Dalton's pictorial circles?", 'options': ['Acharya Kanada', 'Jöns Jacob Berzelius', 'Charles Barkla', 'Democritus'], 'answer': 1, 'solution_steps': ['Step 1: John Dalton used pictorial symbols in 1803.', 'Step 2: In 1813, Jöns Jacob Berzelius proposed 1- or 2-letter alphabetic abbreviations.', "Step 3: Modern IUPAC symbols follow Berzelius's convention."], 'hint': 'John Dalton used pictorial symbols in 1803.', 'explanation': "Modern IUPAC symbols follow Berzelius's convention."}, {'question': 'Q5. Which set of element symbols correctly reflects non-English (Latin/German) roots?', 'options': ['Sodium: So, Iron: Ir, Gold: Go', 'Sodium: Na (natrium), Iron: Fe (ferrum), Gold: Au (aurum), Tungsten: W (wolfram)', 'Potassium: Po, Silver: Si, Lead: Le', 'Copper: Co, Mercury: Me, Tin: Ti'], 'answer': 1, 'solution_steps': ['Step 1: Check Table 8.2 in Section 8.4.', 'Step 2: Na comes from natrium, Fe from ferrum, Au from aurum, and W from wolfram.', 'Step 3: First letter is always uppercase, second letter lowercase.'], 'hint': 'Check Table 8.2 in Section 8.4.', 'explanation': 'First letter is always uppercase, second letter lowercase.'}, {'question': 'Q6. In a neutral atom with Atomic Number Z = 15 and Mass Number A = 31, find the counts of protons, electrons, and neutrons.', 'options': ['15 p⁺, 16 e⁻, 15 n⁰', '15 p⁺, 15 e⁻, 16 n⁰', '16 p⁺, 16 e⁻, 15 n⁰', '31 p⁺, 15 e⁻, 16 n⁰'], 'answer': 1, 'solution_steps': ['Step 1: Atomic number Z = 15 gives 15 protons.', 'Step 2: In a neutral atom, electrons = protons = 15.', 'Step 3: Neutrons n = A - Z = 31 - 15 = 16.'], 'hint': 'Atomic number Z = 15 gives 15 protons.', 'explanation': 'Neutrons n = A - Z = 31 - 15 = 16.'}, {'question': "Q7. What does the term 'nucleons' refer to in Section 8.6?", 'options': ['Electrons in the K shell', 'The sum of protons and neutrons residing in the nucleus (A = Z + n)', 'Only neutrons', 'All particles in an atom including electrons'], 'answer': 1, 'solution_steps': ['Step 1: Protons and neutrons reside inside the nucleus.', 'Step 2: Together they are called nucleons.', 'Step 3: Mass number A equals the total number of nucleons (Z + n).'], 'hint': 'Protons and neutrons reside inside the nucleus.', 'explanation': 'Mass number A equals the total number of nucleons (Z + n).'}, {'question': 'Q8. In Table 8.3, a Lithium atom (Z = 3) has Mass Number A = 7. How many neutrons does it contain?', 'options': ['3', '4', '7', '10'], 'answer': 1, 'solution_steps': ['Step 1: Use A = Z + n.', 'Step 2: n = A - Z = 7 - 3 = 4.', 'Step 3: Lithium-7 has 3 protons and 4 neutrons.'], 'hint': 'Use A = Z + n.', 'explanation': 'Lithium-7 has 3 protons and 4 neutrons.'}, {'question': "Q9. Why were Niels Bohr's energy shells named starting with the letter K (K, L, M, N...)?", 'options': ['Named after Acharya Kanada', 'Following X-ray spectral line designations introduced by Charles Barkla', 'Because K is the 11th element', 'Randomly chosen by John Dalton'], 'answer': 1, 'solution_steps': ['Step 1: Recall Threads of Curiosity in Section 8.2.3.', 'Step 2: Charles Barkla named X-ray lines K, L, M... leaving earlier letters (A–J) free in case deeper lines were found.', 'Step 3: Bohr adopted K, L, M, N for his atomic energy shells.'], 'hint': 'Recall Threads of Curiosity in Section 8.2.3.', 'explanation': 'Bohr adopted K, L, M, N for his atomic energy shells.'}, {'question': 'Q10. Which particle in Table 8.1 has negligible mass compared to a proton and a relative charge of -1?', 'options': ['Proton (p⁺)', 'Neutron (n⁰)', 'Electron (e⁻)', 'Alpha particle'], 'answer': 2, 'solution_steps': ["Step 1: Protons (+1) and neutrons (0) carry almost all the atom's mass.", 'Step 2: Electrons (e⁻) have relative charge -1 and ~1/1836 the mass of a proton.', 'Step 3: Therefore, electrons contribute negligible mass to A.'], 'hint': "Protons (+1) and neutrons (0) carry almost all the atom's mass.", 'explanation': 'Therefore, electrons contribute negligible mass to A.'}]}, {'id': 19, 'title': 'Shells & Valency', 'subtitle': 'Quiz Challenge 3 (10 Questions): Bohr–Bury 2n², First 18 Elements & Valency', 'speech': '', 'questions': [{'question': 'Q1. Using the Bohr–Bury formula 2n², what is the maximum theoretical capacity of the M shell (n = 3)?', 'options': ['8', '18', '32', '6'], 'answer': 1, 'solution_steps': ['Step 1: For the M shell, n = 3.', 'Step 2: Maximum capacity = 2n² = 2 × (3)² = 2 × 9 = 18.', 'Step 3: Answer is 18 electrons.'], 'hint': 'For the M shell, n = 3.', 'explanation': 'Answer is 18 electrons.'}, {'question': 'Q2. What is the maximum number of electrons permitted in the OUTERMOST shell of any atom?', 'options': ['2', '8', '18', '32'], 'answer': 1, 'solution_steps': ['Step 1: Recall the second Bohr–Bury rule in Section 8.7.', 'Step 2: Regardless of theoretical 2n² capacity, the outermost (valence) shell can hold at most 8 electrons.', 'Step 3: (Exception: K shell as outermost holds at most 2.)'], 'hint': 'Recall the second Bohr–Bury rule in Section 8.7.', 'explanation': '(Exception: K shell as outermost holds at most 2.)'}, {'question': 'Q3. What is the electronic configuration (K, L, M) of Aluminium (Z = 13)?', 'options': ['2, 8, 3', '2, 3, 8', '8, 2, 3', '2, 7, 4'], 'answer': 0, 'solution_steps': ['Step 1: Fill K shell first: 2 electrons (11 left).', 'Step 2: Fill L shell next: 8 electrons (3 left).', 'Step 3: Place remaining 3 electrons in M shell → 2, 8, 3.'], 'hint': 'Fill K shell first: 2 electrons (11 left).', 'explanation': 'Place remaining 3 electrons in M shell → 2, 8, 3.'}, {'question': 'Q4. Which element among the first 18 has electronic configuration 2, 8, 6?', 'options': ['Oxygen (Z = 8)', 'Phosphorus (Z = 15)', 'Sulphur (Z = 16)', 'Chlorine (Z = 17)'], 'answer': 2, 'solution_steps': ['Step 1: Sum the electrons: 2 + 8 + 6 = 16.', 'Step 2: In a neutral atom, Z = 16.', 'Step 3: Element 16 is Sulphur (S).'], 'hint': 'Sum the electrons: 2 + 8 + 6 = 16.', 'explanation': 'Element 16 is Sulphur (S).'}, {'question': 'Q5. How many valence electrons does Carbon (Z = 6) have, and what is its valency?', 'options': ['2 valence electrons; valency 2', '4 valence electrons; valency 4', '6 valence electrons; valency 2', '4 valence electrons; valency 2'], 'answer': 1, 'solution_steps': ['Step 1: Carbon (Z = 6) has configuration K = 2, L = 4.', 'Step 2: Its outermost shell has 4 valence electrons.', 'Step 3: For 1–4 valence electrons, valency = number of valence electrons = 4.'], 'hint': 'Carbon (Z = 6) has configuration K = 2, L = 4.', 'explanation': 'For 1–4 valence electrons, valency = number of valence electrons = 4.'}, {'question': 'Q6. What is the valency of Oxygen (Z = 8, configuration 2, 6)?', 'options': ['6', '2', '8', '4'], 'answer': 1, 'solution_steps': ['Step 1: Oxygen has 6 valence electrons (between 5 and 7).', 'Step 2: Use Valency = 8 - valence electrons.', 'Step 3: Valency = 8 - 6 = 2.'], 'hint': 'Oxygen has 6 valence electrons (between 5 and 7).', 'explanation': 'Valency = 8 - 6 = 2.'}, {'question': 'Q7. What is the valency of Fluorine (Z = 9) and Neon (Z = 10) respectively?', 'options': ['F = 7, Ne = 8', 'F = 1, Ne = 0', 'F = 2, Ne = 2', 'F = 1, Ne = 8'], 'answer': 1, 'solution_steps': ['Step 1: F (2, 7) needs 1 electron to complete its octet → valency = 8 - 7 = 1.', 'Step 2: Ne (2, 8) already has a full octet → valency = 0.', 'Step 3: Answer: F = 1, Ne = 0.'], 'hint': 'F (2, 7) needs 1 electron to complete its octet → valency = 8 - 7 = 1.', 'explanation': 'Answer: F = 1, Ne = 0.'}, {'question': "Q8. Which element achieves chemical stability with a 'duplet' (2 electrons) rather than an octet?", 'options': ['Neon', 'Argon', 'Helium', 'Lithium'], 'answer': 2, 'solution_steps': ['Step 1: Helium (Z = 2) has only the K shell, whose maximum capacity is 2.', 'Step 2: With 2 electrons in K, Helium is completely filled (stable duplet).', 'Step 3: Therefore, Helium has valency 0.'], 'hint': 'Helium (Z = 2) has only the K shell, whose maximum capacity is 2.', 'explanation': 'Therefore, Helium has valency 0.'}, {'question': 'Q9. An element has electronic configuration 2, 8, 2. Which element is it and what is its valency?', 'options': ['Sodium; valency 1', 'Magnesium; valency 2', 'Silicon; valency 4', 'Calcium; valency 2'], 'answer': 1, 'solution_steps': ['Step 1: Total electrons = 2 + 8 + 2 = 12 → Z = 12 (Magnesium, Mg).', 'Step 2: Outermost shell has 2 valence electrons.', 'Step 3: Valency = 2.'], 'hint': 'Total electrons = 2 + 8 + 2 = 12 → Z = 12 (Magnesium, Mg).', 'explanation': 'Valency = 2.'}, {'question': 'Q10. Why do Sodium (2, 8, 1) and Chlorine (2, 8, 7) combine in a 1:1 ratio to form NaCl?', 'options': ['Both have 8 valence electrons', 'Sodium has valency 1 (loses 1 e⁻) and Chlorine has valency 1 (gains 1 e⁻) to reach octets', 'Sodium has valency 2', 'Chlorine loses 7 electrons to Sodium'], 'answer': 1, 'solution_steps': ['Step 1: Na (2, 8, 1) easily loses 1 electron to attain stable (2, 8); valency = 1.', 'Step 2: Cl (2, 8, 7) gains 1 electron to attain stable (2, 8, 8); valency = 8 - 7 = 1.', 'Step 3: Equal valencies (1 and 1) give a 1:1 compound NaCl.'], 'hint': 'Na (2, 8, 1) easily loses 1 electron to attain stable (2, 8); valency = 1.', 'explanation': 'Equal valencies (1 and 1) give a 1:1 compound NaCl.'}]}, {'id': 20, 'title': 'Isotopes & Mastery', 'subtitle': 'Quiz Challenge 4 (10 Questions): Isotopes, Average Mass, Isobars & Synthesis', 'speech': '', 'questions': [{'question': 'Q1. How do the three isotopes of Hydrogen—Protium (¹₁H), Deuterium (²₁H), and Tritium (³₁H)—differ?', 'options': ['They have different numbers of protons', 'They all have 1 proton, but have 0, 1, and 2 neutrons respectively', 'They have different atomic numbers Z', 'They are different elements'], 'answer': 1, 'solution_steps': ['Step 1: All three have Z = 1 (1 proton).', 'Step 2: Neutrons n = A - Z: Protium (1-1=0), Deuterium (2-1=1), Tritium (3-1=2).', 'Step 3: Isotopes differ only in neutron count and mass number.'], 'hint': 'All three have Z = 1 (1 proton).', 'explanation': 'Isotopes differ only in neutron count and mass number.'}, {'question': 'Q2. Which radioisotope is used in medicine for treating cancer via radiation therapy?', 'options': ['Uranium-235', 'Cobalt-60', 'Carbon-14', 'Protium'], 'answer': 1, 'solution_steps': ['Step 1: Recall Bridging Science and Society in Section 8.9.1.', 'Step 2: Cobalt-60 (⁶⁰₂₇Co) is used in cancer radiation therapy.', 'Step 3: (Iodine-131 treats thyroid/goitre; Uranium-235 is nuclear fuel; Carbon-14 dates fossils.)'], 'hint': 'Recall Bridging Science and Society in Section 8.9.1.', 'explanation': '(Iodine-131 treats thyroid/goitre; Uranium-235 is nuclear fuel; Carbon-14 dates fossils.)'}, {'question': 'Q3. Which isotope is used to treat goitre (thyroid disorders), and which is used for radiocarbon dating of fossils?', 'options': ['Iodine-131 (thyroid); Carbon-14 (fossil dating)', 'Carbon-14 (thyroid); Uranium-235 (fossil dating)', 'Cobalt-60 (thyroid); Deuterium (fossil dating)', 'Tritium (thyroid); Argon-40 (fossil dating)'], 'answer': 0, 'solution_steps': ['Step 1: The thyroid gland absorbs iodine, so Iodine-131 targets thyroid disorders/goitre.', 'Step 2: Carbon-14 decays at a known rate, enabling radiocarbon dating of ancient organic fossils.', 'Step 3: Answer: Iodine-131 and Carbon-14.'], 'hint': 'The thyroid gland absorbs iodine, so Iodine-131 targets thyroid disorders/goitre.', 'explanation': 'Answer: Iodine-131 and Carbon-14.'}, {'question': 'Q4. An element X exists as 80% ¹⁰X and 20% ¹¹X in nature. What is its average atomic mass?', 'options': ['10.5 u', '10.2 u', '10.8 u', '11.0 u'], 'answer': 1, 'solution_steps': ['Step 1: Compute weighted average: (10 × 80/100) + (11 × 20/100).', 'Step 2: = (10 × 0.80) + (11 × 0.20) = 8.0 + 2.2.', 'Step 3: Average atomic mass = 10.2 u.'], 'hint': 'Compute weighted average: (10 × 80/100) + (11 × 20/100).', 'explanation': 'Average atomic mass = 10.2 u.'}, {'question': 'Q5. Why are Calcium (⁴⁰₂₀Ca), Potassium (⁴⁰₁₉K), and Argon (⁴⁰₁₈Ar) classified as isobars?', 'options': ['They have the same number of protons', 'They are different elements (different Z) with the same mass number A = 40', 'They have identical chemical reactions', 'They have the same number of neutrons'], 'answer': 1, 'solution_steps': ['Step 1: Check Z: Ca = 20, K = 19, Ar = 18 (all different elements).', 'Step 2: Check A: all three have A = 40 total nucleons.', 'Step 3: Different Z and same A defines isobars.'], 'hint': 'Check Z: Ca = 20, K = 19, Ar = 18 (all different elements).', 'explanation': 'Different Z and same A defines isobars.'}, {'question': "Q6. In the modern quantum mechanical model of the atom, what replaces Bohr's flat circular orbits?", 'options': ['Solid watermelon pulp', 'Three-dimensional probability regions called electron clouds', "Dalton's indivisible hooks", 'Stationary neutrons outside the nucleus'], 'answer': 1, 'solution_steps': ['Step 1: Recall the Modern Quantum Outlook at the end of Section 8.9.2.', 'Step 2: Quantum mechanics describes electrons as 3D probability distributions (electron clouds/orbitals) rather than fixed flat paths.', 'Step 3: This 3D electron cloud model is the modern quantum mechanical picture of the atom.'], 'hint': 'Recall the Modern Quantum Outlook at the end of Section 8.9.2.', 'explanation': 'Quantum mechanics describes electrons as 3D probability distributions (electron clouds/orbitals) rather than fixed flat paths.'}, {'question': 'Q7. If an atom has 16 protons and 18 electrons, what is its net charge and which ion is it?', 'options': ['+2 (Mg²⁺)', '-2 (S²⁻)', '-1 (Cl⁻)', '0 (S)'], 'answer': 1, 'solution_steps': ['Step 1: Z = 16 identifies the element as Sulphur (S).', 'Step 2: Net charge = protons - electrons = 16 - 18 = -2.', 'Step 3: It is the sulphide ion S²⁻.'], 'hint': 'Z = 16 identifies the element as Sulphur (S).', 'explanation': 'It is the sulphide ion S²⁻.'}, {'question': 'Q8. In a Revise, Reflect, Refine thought experiment, if electrons were as heavy as protons, how would the mass of a ¹²₆C atom change?', 'options': ['It would stay 12 u', 'Its 6 electrons would add ~6 u, increasing total atomic mass from ~12 u to ~18 u', 'Its atomic number Z would become 12', 'It would lose all neutrons'], 'answer': 1, 'solution_steps': ['Step 1: Normally, 6 protons + 6 neutrons = 12 u, and 6 electrons contribute negligible mass.', 'Step 2: If each electron had 1 u mass, 6 electrons would add 6 u.', 'Step 3: Total mass would rise to ~18 u while Z remains 6.'], 'hint': 'Normally, 6 protons + 6 neutrons = 12 u, and 6 electrons contribute negligible mass.', 'explanation': 'Total mass would rise to ~18 u while Z remains 6.'}, {'question': 'Q9. Which pair of atoms are ISOTOPES of each other?', 'options': ['⁴⁰₁₈Ar and ⁴⁰₂₀Ca', '³⁵₁₇Cl and ³⁷₁₇Cl', '¹⁴₆C and ¹⁴₇N', '¹²₆C and ¹⁶₈O'], 'answer': 1, 'solution_steps': ['Step 1: Isotopes must have the same atomic number Z and different mass numbers A.', 'Step 2: ³⁵₁₇Cl and ³⁷₁₇Cl both have Z = 17 (Chlorine) with A = 35 and 37.', 'Step 3: (⁴⁰Ar/⁴⁰Ca and ¹⁴C/¹⁴N are isobars.)'], 'hint': 'Isotopes must have the same atomic number Z and different mass numbers A.', 'explanation': '(⁴⁰Ar/⁴⁰Ca and ¹⁴C/¹⁴N are isobars.)'}, {'question': 'Q10. Which complete chain correctly summarizes the evolution of atomic structure in Chapter 8?', 'options': ['Bohr → Rutherford → Thomson → Dalton', 'Kanada/Democritus → Dalton (1808) → Thomson (1897) → Rutherford (1911) → Bohr (1913) → Chadwick (1932) → Quantum Cloud', 'Chadwick → Thomson → Dalton → Bohr', 'Rutherford → Dalton → Bohr → Thomson'], 'answer': 1, 'solution_steps': ["Step 1: Ancient ideas (Kanada, Democritus) preceded Dalton's 1808 theory.", 'Step 2: Thomson discovered the electron (1897), Rutherford the nucleus (1911), Bohr stationary shells (1913), and Chadwick the neutron (1932).', 'Step 3: Modern quantum mechanics refines shells into 3D electron clouds.'], 'hint': "Ancient ideas (Kanada, Democritus) preceded Dalton's 1808 theory.", 'explanation': 'Modern quantum mechanics refines shells into 3D electron clouds.'}]}]
